local FacadeFactory = require(script.Parent.FacadeFactory)

-- 本方法会为 handler 额外添加一个参数 TangSengFacade
return function(handler: (...any) -> (), argsCount: number, isPlayerScope: boolean?)
	return function(...)
		local args = { ... }
		local facade = nil
		if isPlayerScope then
			local player = args[1]
			assert(player and player:IsA("Player"), "玩家域调用的第一个参数必须是 Player 类型")
			facade = FacadeFactory.GetFacadeOfPlayer(player)
		else
			facade = FacadeFactory.GetRootFacade()
		end

		if not argsCount or argsCount <= 0 then
			return handler(unpack(args), facade)
		elseif argsCount == 1 then
			return handler(args[1], facade)
		elseif argsCount == 2 then
			return handler(args[1], args[2], facade)
		elseif argsCount == 3 then
			return handler(args[1], args[2], args[3], facade)
		elseif argsCount == 4 then
			return handler(args[1], args[2], args[3], args[4], facade)
		elseif argsCount == 5 then
			return handler(args[1], args[2], args[3], args[4], args[5], facade)
		elseif argsCount == 6 then
			return handler(args[1], args[2], args[3], args[4], args[5], args[6], facade)
		elseif argsCount == 7 then
			return handler(args[1], args[2], args[3], args[4], args[5], args[6], args[7], facade)
		elseif argsCount == 8 then
			return handler(args[1], args[2], args[3], args[4], args[5], args[6], args[7], args[8], facade)
		end
	end
end
